from collections import Counter
def diff(I,O): 
    return [(r,c,I[r][c],O[r][c]) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]!=O[r][c]]

def regions(g,k):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==k and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=a<h and 0<=b<w and g[a][b]==k and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                res.append(cells)
    return res

for name,(I,O) in zip(['D'+str(i+1) for i in range(7)], pairs):
