    print(name, sorted(newc), 'changed cells:', len(chgs))
    cnt=Counter(x for row in I for x in row)
    sizes={k:sorted([len(r) for r in regions(I,k)], reverse=True) for k in set(v for row in I for v in row)}
    for k in sorted(sizes): print('  ',k,'regions sizes:',sizes[k],'total',sum(sizes[k]))

