# Let me find the marker lines per demo — the "marker" color forms long straight structures
# In each demo there's also an "indicator" line of a different color that marks position along the grid edge?
# Classic pattern: marker arm, indicator arm, and region to recolor.
# Let me identify lines (straight connected components of single color)
def is_line(regions_g, color):
    rs = regions(regions_g, color)
    results = []
    for reg in rs:
        xs = [c for r, c in reg]
        ys = [r for r, c in reg]
        # horizontal line if all rows same
        if len(set(ys)) == 1 and len(xs) > 5:
            results.append(('horizontal', set(ys.pop()), frozenset(sorted(xs))))
        elif len(set(xs)) == 1 and len(ys) > 5:
            results.append(('vertical', set(xs.pop()), frozenset(sorted(ys))))
    return results

for name,(I,O) in zip(['D'+str(i+1) for i in range(7)], pairs):
