t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
def diff(I,O): return [(r,c,I[r][c],O[r][c]) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]!=O[r][c]]
def regions(g,k):
    h,w=len(g),len(g[0]); seen=set(); res=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==k and (i,j) not in seen:
                stack=[(i,j)]; seen.add((i,j)); cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                        if 0<=a<h and 0<=b<w and g[a][b]==k and (a,b) not in seen:
                            seen.add((a,b)); stack.append((a,b))
                res.append(cells)
    return res
# Pair analysis with feature table
changed_regions = []
for i in range(8):
    I,O = G[f'Demo pair {i+1} input'], G[f'Demo pair {i+1} output']
    chgs = diff(I,O); oldc = set(v for _,_,v,_ in chgs); nrc = set(v for _,_,_,v in chgs)
    regs = regions(I,oldc)
    ftab = []
    for reg in regs:
        rs=[row[0] for row in reg]; cs=[col[1] for col in reg]
        min_r,max_r,min_c,max_c=min(rs),max(rs),min(cs),max(cs)
        sz=len(reg)
        touchT=(min_r==0); touchB=(max_r==len(I)-1); touchL=(min_c==0); touchR=(max_c==len(I[0])-1)
        touches=str(touchT)+'-'+str(touchB)+'-'+str(touchL)+'-'+str(touchR)
        degs=[sum(1 for a,b in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if 0<=a<len(I) and 0<=b<len(I[0]) and I[a][b]==oldc) for p in reg]
        avg=sum(degs)/len(degs)
        corners=sum(1 for p in reg if sum(1 for a,b in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)) if 0<=a<len(I) and 0<=b<len(I[0]) and I[a][b]==oldc)<=1)
        is_changed='CHANGED' if set(reg) == set(p for (r,c,v,o) in chgs) else ''
        ftab.append(dict(sz=sz,bbox=(min_r,max_r,min_c,max_c),touches=touches,corners=corners,avg_deg=round(avg,2),is_changed=is_changed))
    changed_regions.append({'pair':i+1,'old':sorted(oldc),'new':sorted(nrc),'cells':chgs,'ftab':ftab})
    print('Pair',i+1,', old->new:', sorted(oldc),'->', sorted(nrc))
    for e in ftab: print(json.dumps(e))

